from fastapi import APIRouter, Depends, HTTPException, Request, Response
from fastapi.routing import APIRoute
from typing import Callable

class SignedWebhookRoute(APIRoute):
    def get_route_handler(self) -> Callable:
        original_route_handler = super().get_route_handler()
        async def custom_handler(request: Request) -> Response:
            # Always route through original_route_handler so dependencies are executed
            return await original_route_handler(request)
        return custom_handler

router = APIRouter(route_class=SignedWebhookRoute, prefix="/projects")

@router.post("/{project_id}/trigger-build", dependencies=[Depends(verify_tenant_boundary)])
async def trigger_project_build(project_id: str, branch: str = "main"):
    job = await BuildEngine.dispatch_build(project_id=project_id, branch=branch)
    return {"project_id": project_id, "build_id": job.id, "status": "QUEUED"}
